import com.hbm.main.ResourceManager;
import com.hbm.render.item.ItemRenderBase;
import com.hbm.tileentity.machine.TileEntityAshpit;

import net.minecraft.client.renderer.tileentity.TileEntitySpecialRenderer;
import net.minecraft.item.Item;
import net.minecraft.tileentity.TileEntity;
import net.minecraftforge.client.IItemRenderer;

public class RenderAshpit extends TileEntitySpecialRenderer implements IItemRendererProvider {

	@Override
	public void renderTileEntityAt(TileEntity tile, double x, double y, double z, float interp) {
		GL11.glPushMatrix();
		GL11.glTranslated(x + 0.5D, y, z + 0.5D);
		GL11.glEnable(GL11.GL_LIGHTING);
		GL11.glEnable(GL11.GL_CULL_FACE);

		switch(tile.getBlockMetadata() - BlockDummyable.offset) {
		case 3: GL11.glRotatef(0, 0F, 1F, 0F); break;
		case 5: GL11.glRotatef(90, 0F, 1F, 0F); break;
		case 2: GL11.glRotatef(180, 0F, 1F, 0F); break;
		case 4: GL11.glRotatef(270, 0F, 1F, 0F); break;
		}
		GL11.glRotatef(-90, 0F, 1F, 0F);

		TileEntityAshpit oven = (TileEntityAshpit) tile;

		bindTexture(ResourceManager.ashpit_tex);
		ResourceManager.heater_oven.renderPart("Main");

		GL11.glPushMatrix();
		float door = oven.prevDoorAngle + (oven.doorAngle - oven.prevDoorAngle) * interp;
		GL11.glTranslated(0, 0, door * 0.75D / 135D);
		ResourceManager.heater_oven.renderPart("Door");
		GL11.glPopMatrix();

		if(oven.isFull) {
			ResourceManager.heater_oven.renderPart("InnerBurning");
		} else {
			ResourceManager.heater_oven.renderPart("Inner");
		}

		GL11.glPopMatrix();
	}

	@Override
	public Item getItemForRenderer() {
		return Item.getItemFromBlock(ModBlocks.machine_ashpit);
	}

	@Override
	public IItemRenderer getRenderer() {
		return new ItemRenderBase() {
			public void renderInventory() {
				GL11.glTranslated(0, -1, 0);
				GL11.glScaled(3.25, 3.25, 3.25);
			}
			public void renderCommon() {
				bindTexture(ResourceManager.ashpit_tex);
				ResourceManager.heater_oven.renderPart("Main");
				ResourceManager.heater_oven.renderPart("Door");
			}};
	}
}

package com.hbm.render.tileentity;

import org.lwjgl.opengl.GL11;

import com.hbm.blocks.BlockDummyable;
import com.hbm.blocks.ModBlocks;
import com.hbm.main.ResourceManager;
import com.hbm.render.item.ItemRenderBase;
import com.hbm.render.util.RenderDecoItem;
import com.hbm.tileentity.machine.TileEntityMachineArcWelder;

import net.minecraft.client.renderer.entity.RenderItem;
import net.minecraft.client.renderer.tileentity.TileEntitySpecialRenderer;
import net.minecraft.entity.item.EntityItem;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraft.tileentity.TileEntity;
import net.minecraftforge.client.IItemRenderer;

public class RenderArcWelder extends TileEntitySpecialRenderer implements IItemRendererProvider {

	private RenderItem itemRenderer = new RenderDecoItem(this);

	@Override
	public void renderTileEntityAt(TileEntity tile, double x, double y, double z, float interp) {
		GL11.glPushMatrix();
		GL11.glTranslated(x + 0.5, y, z + 0.5);
		GL11.glEnable(GL11.GL_LIGHTING);
		GL11.glEnable(GL11.GL_CULL_FACE);

		switch(tile.getBlockMetadata() - BlockDummyable.offset) {
		case 2: GL11.glRotatef(90, 0F, 1F, 0F); break;
		case 4: GL11.glRotatef(180, 0F, 1F, 0F); break;
		case 3: GL11.glRotatef(270, 0F, 1F, 0F); break;
		case 5: GL11.glRotatef(0, 0F, 1F, 0F); break;
		}

		GL11.glTranslated(-0.5, 0, 0);

		bindTexture(ResourceManager.arc_welder_tex);
		ResourceManager.arc_welder.renderAll();

		TileEntityMachineArcWelder welder = (TileEntityMachineArcWelder) tile;
		if(welder.display != null) {
			GL11.glPushMatrix();
			GL11.glTranslated(0.0625D * 2.5D, 1.125D, 0D);
			GL11.glEnable(GL11.GL_LIGHTING);
			GL11.glRotatef(90, 0F, 1F, 0F);
			GL11.glRotatef(-90, 1F, 0F, 0F);

			if(welder.display != null) {
				ItemStack stack = welder.display.copy();

				EntityItem item = new EntityItem(null, 0.0D, 0.0D, 0.0D, stack);
				item.getEntityItem().stackSize = 1;
				item.hoverStart = 0.0F;

				RenderItem.renderInFrame = true;
				GL11.glScaled(1.5, 1.5, 1.5);
				this.itemRenderer.doRender(item, 0.0D, 0.0D, 0.0D, 0.0F, 0.0F);
				RenderItem.renderInFrame = false;
			}
			GL11.glPopMatrix();
		}

		GL11.glPopMatrix();
	}

	@Override
	public Item getItemForRenderer() {
		return Item.getItemFromBlock(ModBlocks.machine_arc_welder);
	}

	@Override
	public IItemRenderer getRenderer() {
		return new ItemRenderBase( ) {
			public void renderInventory() {
				GL11.glTranslated(0, -2, 0);
				GL11.glScaled(4, 4, 4);
			}
			public void renderCommon() {
				bindTexture(ResourceManager.arc_welder_tex);
				ResourceManager.arc_welder.renderAll();
			}};
	}
}

package com.hbm.render.tileentity;

import java.util.Random;

import org.lwjgl.opengl.GL11;

import com.hbm.blocks.ModBlocks;
import com.hbm.items.ModItems;
import com.hbm.items.machine.ItemBatteryPack.EnumBatteryPack;
import com.hbm.lib.RefStrings;
import com.hbm.main.ResourceManager;
import com.hbm.render.item.ItemRenderBase;
import com.hbm.render.util.BeamPronter;
import com.hbm.render.util.HorsePronter;
import com.hbm.render.util.BeamPronter.EnumBeamType;
import com.hbm.render.util.BeamPronter.EnumWaveType;
import com.hbm.tileentity.machine.storage.TileEntityBatterySocket;
import com.hbm.util.EnumUtil;

import net.minecraft.client.renderer.tileentity.TileEntitySpecialRenderer;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraft.tileentity.TileEntity;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.Vec3d;
import net.minecraftforge.client.IItemRenderer;

public class RenderBatterySocket extends TileEntitySpecialRenderer implements IItemRendererProvider {

	private static ResourceLocation blorbo = new ResourceLocation(RefStrings.MODID, "textures/models/horse/sunburst.png");

	@Override
	public void renderTileEntityAt(TileEntity tile, double x, double y, double z, float interp) {
		GL11.glPushMatrix();
		GL11.glTranslated(x + 0.5, y, z + 0.5);
		GL11.glEnable(GL11.GL_LIGHTING);
		GL11.glEnable(GL11.GL_CULL_FACE);

		switch(tile.getBlockMetadata() - 10) {
		case 2: GL11.glRotatef(90, 0F, 1F, 0F); break;
		case 4: GL11.glRotatef(180, 0F, 1F, 0F); break;
		case 3: GL11.glRotatef(270, 0F, 1F, 0F); break;
		case 5: GL11.glRotatef(0, 0F, 1F, 0F); break;
		}

		GL11.glTranslated(-0.5, 0, 0.5);

		TileEntityBatterySocket socket = (TileEntityBatterySocket) tile;

		GL11.glShadeModel(GL11.GL_SMOOTH);
		bindTexture(ResourceManager.battery_socket_tex);
		ResourceManager.battery_socket.renderPart("Socket");

		ItemStack render = socket.syncStack;
		if(render != null) {

			if(render.getItem() == ModItems.battery_pack) {
				EnumBatteryPack pack = EnumUtil.grabEnumSafely(EnumBatteryPack.class, render.getItemDamage());
				bindTexture(pack.texture);
				ResourceManager.battery_socket.renderPart(pack.isCapacitor() ? "Capacitor" : "Battery");
			} else if(render.getItem() == ModItems.battery_sc) {
				bindTexture(ResourceManager.battery_sc_tex);
				ResourceManager.battery_socket.renderPart("Battery");
			} else if(render.getItem() == ModItems.battery_creative) {
				GL11.glPushMatrix();
				GL11.glScaled(0.75, 0.75, 0.75);
				GL11.glRotated((socket.getWorldObj().getTotalWorldTime() % 360 + interp) * 25D, 0, -1, 0);
				this.bindTexture(blorbo);
				HorsePronter.reset();
				HorsePronter.enableHorn();
				HorsePronter.pront();
				GL11.glPopMatrix();

				Random rand = new Random(tile.getWorldObj().getTotalWorldTime() / 5);
				rand.nextBoolean();

				for(int i = -1; i <= 1; i += 2) for(int j = -1; j <= 1; j += 2) if(rand.nextInt(4) == 0) {
					GL11.glPushMatrix();
					GL11.glTranslated(0, 0.75, 0);
					BeamPronter.prontBeam(new Vec3d(0.4375 * i, 1.1875, 0.4375 * j), EnumWaveType.RANDOM, EnumBeamType.SOLID, 0x404040, 0x002040, (int)(System.currentTimeMillis() % 1000) / 50, 15, 0.0625F, 3, 0.025F);
					BeamPronter.prontBeam(new Vec3d(0.4375 * i, 1.1875, 0.4375 * j), EnumWaveType.RANDOM, EnumBeamType.SOLID, 0x404040, 0x002040, (int)(System.currentTimeMillis() % 1000) / 50, 1, 0, 3, 0.025F);
					GL11.glPopMatrix();
				}
			} else if(render.getItem() == ModItems.core_angel) {
				GL11.glPushMatrix();
				GL11.glScaled(2, 2, 2);
				GL11.glRotated((socket.getWorldObj().getTotalWorldTime() % 360 + interp) * 5D, 0, -1, 0);
				this.bindTexture(ResourceManager.bfangel_tex);
				ResourceManager.bfangel.renderOnly("body");
				GL11.glPopMatrix();

				Random rand = new Random(tile.getWorldObj().getTotalWorldTime() / 5);
				rand.nextBoolean();

				for(int i = -1; i <= 1; i += 2) for(int j = -1; j <= 1; j += 2) if(rand.nextInt(4) == 0) {
					GL11.glPushMatrix();
					GL11.glTranslated(0, 0.75, 0);
					BeamPronter.prontBeam(new Vec3d(0.4375 * i, 1.1875, 0.4375 * j), EnumWaveType.RANDOM, EnumBeamType.SOLID, 0x404040, 0x002040, (int)(System.currentTimeMillis() % 1000) / 50, 15, 0.0625F, 3, 0.025F);
					BeamPronter.prontBeam(new Vec3d(0.4375 * i, 1.1875, 0.4375 * j), EnumWaveType.RANDOM, EnumBeamType.SOLID, 0x404040, 0x002040, (int)(System.currentTimeMillis() % 1000) / 50, 1, 0, 3, 0.025F);
					GL11.glPopMatrix();
				}
			}

		}

		GL11.glShadeModel(GL11.GL_FLAT);

		GL11.glPopMatrix();
	}

	@Override
	public Item getItemForRenderer() {
		return Item.getItemFromBlock(ModBlocks.machine_battery_socket);
	}

	@Override
	public IItemRenderer getRenderer() {
		return new ItemRenderBase() {
			public void renderInventory() {
				GL11.glTranslated(0, -2, 0);
				GL11.glScaled(5, 5, 5);
			}
			public void renderCommon() {
				GL11.glShadeModel(GL11.GL_SMOOTH);
				bindTexture(ResourceManager.battery_socket_tex);
				ResourceManager.battery_socket.renderPart("Socket");
				GL11.glShadeModel(GL11.GL_FLAT);
			}};
	}
}

