			GL11.glEnable(GL11.GL_LIGHTING);

			GL11.glPopAttrib();
			GL11.glPopMatrix();
		} else {
			ResourceManager.heater_firebox.renderPart("InnerEmpty");
		}

		GL11.glPopMatrix();
	}

